pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // First, make a call to deposit via fallback to initialize depositsCount
        vm.deal(address(this), 1 ether);
        (bool success, ) = address(c).call{value: 1 ether}("");
        require(success, "fallback call failed");
        // At this point: C.depositsCount() == 1, M.depositsCount() == 2

        // Now call sendMoney to owner with 1 wei (no ether needed, just a call)
        c.sendMoney(address(this), 1);

        // After sendMoney call:
        // Reference: depositsCount was incremented by 1 from fallback => 1, sendMoney doesn't affect it => 1
        // Bug: depositsCount was incremented by 2 from fallback => 2, sendMoney doesn't affect it => 2
        // So the divergence is: P.depositsCount() == 1, M.depositsCount() == 2
        assertTrue(c.depositsCount() == 1, "depositsCount should be 1 in reference");
    }
}

