        address owner = address(this);
        vm.deal(owner, 1 ether);
        vm.prank(owner);
        (bool success, ) = address(c).call{value: 1 ether}("");
        require(success, "fallback failed");

        // Now call sendMoney(owner, 1)
        vm.deal(address(c), 1 ether); // ensure contract has balance to send
        c.sendMoney(owner, 1);

        // Reference: depositsCount = 1 (fallback) + 1 (sendMoney call's fallback? No, sendMoney uses .call not fallback) 
        // Actually, fallback incremented by 1, sendMoney does not trigger fallback, so reference = 1+1 = 2; bug = 1+2 = 3.
        assertTrue(c.depositsCount() == 2, "depositsCount should be 2 in correct version");
    }
}

