pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund the contract with 1 wei via fallback
        vm.deal(address(this), 1 ether);
        vm.prank(address(this));
        (bool success, ) = address(c).call{value: 1 wei}("");
        require(success, "fallback failed");
        // depositsCount is now 1 (reference) or 2 (buggy)

        // Call sendMoney to itself — no new Ether sent, so fallback not triggered
        vm.prank(c.owner());
        c.sendMoney{value: 0}(address(c), 0);

        // In the reference, depositsCount remains 1
        // In the buggy version, depositsCount becomes 3 (original 1 + 2 via sendMoney's internal call)
        assertTrue(c.depositsCount() == 1, "depositsCount should be 1 in reference");
    }
}

