contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address owner = address(this);
        vm.deal(address(c), 0);
        // First fallback call
        (bool success1,) = address(c).call{value: 1}("");
        // Second fallback call
        (bool success2,) = address(c).call{value: 1}("");
        require(success1 && success2, "fallback failed");
        // Now call sendMoney(owner, 1)
        c.sendMoney(owner, 1);
        // Reference: after 2 fallback calls (++ each) depositsCount = 2, then sendMoney sends 1 wei to owner (no fallback triggered), so depositsCount stays 2; but wait! sendMoney uses .call which DOES trigger fallback in the recipient? No - the call is to owner (an EOA) so no. Actually sendMoney calls _target.call -> if _target is a contract that would trigger fallback, but owner is an address (not contract). So no further change. So reference: depositsCount = 2. Buggy: depositsCount = 2 fallsbacks gave 4, sendMoney no change = 4. But we need a difference after sendMoney. Let's fix: After fallback twice, reference depositsCount = 2, buggy = 4. Then sendMoney does NOT change depositsCount, so reference=2, buggy=4. Wait assertion must be after sendMoney. The difference is still 2 vs 4. But the problem says "after a call to sendMoney(...) completes, the value of state variable depositsCount differs: P.depositsCount() != M.depositsCount()". So we assert c.depositsCount() != something? No: Need to show reference passes and bug breaks. Let's assert c.depositsCount() == 2? That would pass on reference but fail on buggy (which has 4). But previous rejected patterns: after two fallbacks and sendMoney, reference=2, buggy=4 is valid. But note: In reference, fallback does depositsCount++. After 2 calls: 2. Then sendMoney(owner,1) does NOT change depositsCount. So reference=2. Buggy: each fallback does +=2, so after 2 calls: 4. Then no change. So we assert c.depositsCount() == 2. That passes on reference, fails on buggy. This is a concrete witness. Good.
        assertTrue(c.depositsCount() == 2);
    }
}

