pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Owner sends 1 wei to the contract itself
        vm.deal(address(c), 1);
        // Now call withdrawAll from the owner to check the balance used
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }
        // Reference: address(this).balance was 1, so withdrawAll succeeds (no revert)
        // Bug: address(this).balance replaced with 0, so withdraw(0) sends 0 and also succeeds
        // Both succeed — need a different observable. Instead, read address(c).balance after withdrawAll
        // In reference, balance after withdrawal = 0; in bug, also 0. So no divergence there.
        // Let's instead check the return of withdrawAll — but it's a void function.
        // The difference stated: after sendMoney(...), the value of state variable withdrawAll differs.
        // withdrawAll is a function, not a state variable. So the intended difference must be:
        // P.withdrawAll() returns different than M.withdrawAll() after a sendMoney call.
        // Since withdrawAll is a void function, the statement likely means the effect on balance differs.
        // Let's test that after sendMoney, calling withdrawAll leads to different final balances.

        // Reset: new contract
        c = new C();
        address owner = address(this); // contract deployer
        vm.deal(owner, 10 ether);
        // Send 1 wei to the contract via sendMoney
        c.sendMoney(address(c), 1);
        // Now call withdrawAll
        c.withdrawAll();
        // The reference contract will send address(this).balance (1 wei) back to owner.
        // The buggy contract will send 0 wei.
        // Check owner's balance: in reference, owner gets 1 wei more than initial (plus leftover gas costs minor)
        // Better: check address(c).balance after withdrawAll: reference => 0, bug => 1
        assertTrue(address(c).balance == 0, "reference empties contract, bug leaves 1 wei");
    }
}

